import pandas as pd
import numpy as np

# Load market data
data = pd.read_csv('market_data.csv')

# Calculate indicators
data['OBV'] = data['Close'].diff().fillna(0) * data['Volume']
data['OBV'] = data['OBV'].cumsum()
data['ADX'] = data['High'].rolling(window=14).max() - data['Low'].rolling(window=14).min()
data['ADX'] = data['ADX'] / data['Close']

# Define entry and exit rules
def check_long_entry(row):
  return row['OBV'] > row['OBV'].shift(1) and row['ADX'] > 20

def check_short_entry(row):
  return row['OBV'] < row['OBV'].shift(1) and row['ADX'] > 20

def check_long_exit(row):
  return row['OBV'] < row['OBV'].shift(1) or row['ADX'] < 20

def check_short_exit(row):
  return row['OBV'] > row['OBV'].shift(1) or row['ADX'] < 20

# Apply entry and exit rules
data['long_entry'] = data.apply(check_long_entry, axis=1)
data['short_entry'] = data.apply(check_short_entry, axis=1)
data['long_exit'] = data.apply(check_long_exit, axis=1)
data['short_exit'] = data.apply(check_short_exit, axis=1)

# Implement risk management
def calculate_position_size(equity):
  return 0.02 * equity

def calculate_stop_loss(entry_price):
  return entry_price * 0.02

def calculate_take_profit(entry_price):
  return entry_price * 0.05

# Backtest the strategy
equity = 100000
positions = []
for i in range(1, len(data)):
  if data['long_entry'].iloc[i]:
    entry_price = data['Close'].iloc[i]
    position_size = calculate_position_size(equity)
    stop_loss = calculate_stop_loss(entry_price)
    take_profit = calculate_take_profit(entry_price)
    positions.append({'entry_price': entry_price, 'position_size': position_size, 'stop_loss': stop_loss, 'take_profit': take_profit})
  elif data['short_entry'].iloc[i]:
    entry_price = data['Close'].iloc[i]
    position_size = calculate_position_size(equity)
    stop_loss = calculate_stop_loss(entry_price)
    take_profit = calculate_take_profit(entry_price)
    positions.append({'entry_price': entry_price, 'position_size': position_size, 'stop_loss': stop_loss, 'take_profit': take_profit})
  elif data['long_exit'].iloc[i]:
    for position in positions:
      if position['entry_price'] == data['Close'].iloc[i-1]:
        positions.remove(position)
        equity += position['position_size'] * (data['Close'].iloc[i] - position['entry_price'])
  elif data['short_exit'].iloc[i]:
    for position in positions:
      if position['entry_price'] == data['Close'].iloc[i-1]:
        positions.remove(position)
        equity += position['position_size'] * (position['entry_price'] - data['Close'].iloc[i])

# Evaluate the strategy
print('Final Equity:', equity)
print('Number of Trades:', len(positions))
"
